Download Albums
We fetch the release groups for Pink Floyd and Stone Temple Pilots via the MusicBrainz API, filtering for studio albums.

fetch_albums &lt;- function(artist_id, artist_name) {
  Sys.sleep(1.5)
  url &lt;- paste0(
    "https://musicbrainz.org/ws/2/release-group?artist=",
    artist_id,
    "&limit=100&fmt=json"
  )

  res &lt;- request(url) |&gt;
    req_headers("User-Agent" = "CourseProject/1.0 (student@example.edu)") |&gt;
    req_throttle(rate = 0.5) |&gt;
    req_retry(
      max_tries = 5,
      is_transient = \(resp) resp_status(resp) %in% c(429, 503),
      after = \(resp) 3
    ) |&gt;
    req_perform() |&gt;
    resp_body_json()

  rgs &lt;- res[["release-groups"]]

  tibble(
    id = map_chr(rgs, "id"),
    artist = artist_name,
    title = map_chr(rgs, "title"),
    primary_type = map_chr(rgs, \(x) x[["primary-type"]] %||% NA_character_),
    secondary_types = map_chr(rgs, \(x) paste(x[["secondary-types"]], collapse = ", ")),
    release_date = map_chr(rgs, \(x) x[["first-release-date"]] %||% NA_character_)
  ) |&gt;
    filter(primary_type == "Album", secondary_types == "") |&gt;
    mutate(cover_url = paste0("https://coverartarchive.org/release-group/", id, "/front-250")) |&gt;
    select(artist, title, release_date, cover_url)
}

if (file.exists("albums.csv") && nrow(read_csv("albums.csv", show_col_types = FALSE)) &gt; 0) {
  albums &lt;- read_csv("albums.csv", show_col_types = FALSE)
} else {
  artists &lt;- tribble(
    ~artist, ~id,
    "Pink Floyd", "83d91898-7763-47d7-b03b-b92132375c47",
    "Stone Temple Pilots", "8c32bb01-58a3-453b-8050-8c0620edb0e5"
  )

  albums &lt;- map2(artists$id, artists$artist, fetch_albums) |&gt;
    list_rbind() |&gt;
    arrange(artist, release_date)

  write_csv(albums, "albums.csv")
}
